"""The README's results block is generated by the code, so it cannot go stale."""

import re
import unittest
from contextlib import redirect_stdout
from io import StringIO
from pathlib import Path

from countersign.cli import main

README = Path(__file__).resolve().parent.parent / "README.md"


class ReadmeTests(unittest.TestCase):
    def test_results_block_matches_the_benchmark(self):
        text = README.read_text(encoding="utf-8")
        block = re.search(r"<!-- benchmark:start -->\n(.*?)\n<!-- benchmark:end -->", text, re.S)
        self.assertIsNotNone(block, "README has no benchmark block")
        out = StringIO()
        with redirect_stdout(out):
            self.assertEqual(main(["benchmark", "--markdown"]), 0)
        self.assertEqual(block.group(1).strip(), out.getvalue().strip(),
                         "README results are stale: run python -m countersign benchmark --markdown")


if __name__ == "__main__":
    unittest.main()
